    {
      "id": "variance_and_routing_conclusion",
      "tier": "important",
      "method": "llm",
      "question": "Did the final answer correctly report the linked count evidence and explain why this exception required the investigation routing?",
      "pass_anchor": "Pass if the answer identifies CR-25Q3-TE-DISC / sample S-25Q3-TE-DISC and the preferred primary result RR-TE-DISC-A (not the recount attachment RR-TE-DISC-B), reports book quantity 40 and latest verified quantity 20 for the represented 20-SKU cohort, calculates a signed shortage of 20 units at the approved weighted-average cost of $2,750 per unit, and therefore a proposed signed adjustment of -$55,000.00. It must recognize that the $55,000.00 absolute variance meets the approved $50,000.00 materiality threshold and explain that F-01 routes the case to Marcus Bell, Inventory Control Manager, for an open investigation; the evidence-backed cause classification is unrecorded issue because movement/issue postings were not completed or linked to the dispatch/work-order support. Allow ordinary formatting differences and equivalent wording, but not a different result version, sign, amount, threshold conclusion, owner, or cause.",
      "files": [
        "answer.md"
      ]
    },
    {
      "id": "action_summary",
      "tier": "important",
      "method": "llm",
      "question": "Did the final answer accurately summarize the database action it completed?",
      "pass_anchor": "Pass if the answer says it created or updated the investigation for CR-25Q3-TE-DISC and records the substantive final state: owner Marcus Bell, cause_code unrecorded_issue, proposed adjustment -$55,000.00, and resolution status open. It should make clear that unrelated investigations and source files were not changed.",
      "files": [
        "answer.md"
      ]
    },
    {
      "id": "unrelated_records_preserved",
      "tier": "sanity",
      "method": "rule",
      "fn": "check_unrelated_records_preserved",
      "question": "Were unrelated investigations preserved while the target was updated?",
      "weight": 0
    }
  ],
  "check_code": "from pathlib import Path\nimport sqlite3\n\n\ndef _db(ws):\n    return Path(ws).parent / \"system\" / \"windsor_cycle_count_workbench\" / \"state.db\"\n\n\ndef _target(ws):\n    con = sqlite3.connect(_db(ws))\n    con.row_factory = sqlite3.Row\n    row = con.execute(\n        \"SELECT * FROM discrepancy_investigations WHERE investigation_id=?\",\n        (\"INVEST-25Q3-TE-DISC\",),\n    ).fetchone()\n    con.close()\n    return row\n\n\ndef check_target_result_link(ws):\n    row = _target(ws)\n    expected = {\n        \"count_result_id\": \"CR-25Q3-TE-DISC\",\n        \"result_row_id\": \"RR-TE-DISC-A\",\n    }\n    if row is None:\n        return {\"score\": 0, \"detail\": \"target investigation is missing\"}\n    missing = [f\"{k}={v}\" for k, v in expected.items() if row[k] != v]\n    return {\"score\": 0 if missing else 1, \"detail\": \"mismatch: \" + \", \".join(missing) if missing else \"primary result link is correct\"}\n\n\ndef check_owner(ws):\n    row = _target(ws)\n    ok = row is not None and row[\"assigned_to\"] == \"Marcus Bell\"\n    return {\"score\": 1 if ok else 0, \"detail\": \"owner is Marcus Bell\" if ok else f\"assigned_to={row['assigned_to'] if row else None}\"}\n\n\ndef check_cause(ws):\n    row = _target(ws)\n    ok = row is not None and row[\"cause_code\"] == \"unrecorded_issue\"\n    return {\"score\": 1 if ok else 0, \"detail\": \"cause is unrecorded_issue\" if ok else f\"cause_code={row['cause_code'] if row else None}\"}\n\n\ndef check_proposed_adjustment(ws):\n    row = _target(ws)\n    ok = row is not None and row[\"proposed_adjustment_cents\"] == -5500000\n    return {\"score\": 1 if ok else 0, \"detail\": \"signed adjustment is -5,500,000 cents\" if ok else f\"proposed_adjustment_cents={row['proposed_adjustment_cents'] if row else None}\"}\n\n\ndef check_open_status(ws):\n    row = _target(ws)\n    ok = row is not None and row[\"resolution_status\"] == \"open\"\n    return {\"score\": 1 if ok else 0, \"detail\": \"resolution status is open\" if ok else f\"resolution_status={row['resolution_status'] if row else None}\"}\n\n\ndef check_unrelated_records_preserved(ws):\n    con = sqlite3.connect(_db(ws))\n    con.row_factory = sqlite3.Row\n    row = con.execute(\n        \"SELECT investigation_id,result_row_id,count_result_id,assigned_to,assigned_on,cause_code,cause_analysis,proposed_adjustment_cents,resolution_status,evidence_uri,resolved_on FROM discrepancy_investigations WHERE investigation_id=?\",\n        (\"INVEST-25Q3-ORPHAN-01\",),\n    ).fetchone()\n    con.close()\n    expected = {\n        \"investigation_id\": \"INVEST-25Q3-ORPHAN-01\",\n        \"result_row_id\": None,\n        \"count_result_id\": \"CR-25Q2-RETIRED-7741\",\n        \"assigned_to\": \"Archive Migration Queue\",\n        \"assigned_on\": \"2025-07-02\",\n        \"cause_code\": \"retired_reference\",\n        \"cause_analysis\": \"Migrated investigation points to a retired pre-production count result. It is retained for history and excluded from the 2025-Q3 discrepancy population.\",\n        \"proposed_adjustment_cents\": -184250,\n        \"resolution_status\": \"retired_reference\",\n        \"evidence_uri\": \"audit-evidence://archive/CR-25Q2-RETIRED-7741\",\n        \"resolved_on\": \"2025-07-03\",\n    }\n    if row is None:\n        return {\"score\": 0, \"detail\": \"unrelated orphan investigation is missing\"}\n    mismatches = [f\"{k}={row[k]!r}\" for k, v in expected.items() if row[k] != v]\n    return {\"score\": 0 if mismatches else 1, \"detail\": \"unrelated record changed: \" + \", \".join(mismatches) if mismatches else \"unrelated orphan investigation preserved\"}\n",
  "gold_answer": null,
  "input": "both",
  "act": "mutate_db",
  "output": "none",
  "reward": "rl_grade"
}
